const inlineme = globalThis['~Natives_inlineme'] ?? (function(){});
const inner = function(a, b) { inlineme(); return a + b; };
export function outer(a, b) { return inner(a, b); }

const inlineme_n = globalThis['~Natives_inlineme_n'] ?? (function(){});
const inner  = function(a, b) { inlineme_n(1); return a + b; };
const middle = function(a, b) { return inner(a, b); };
export function outer(a, b) { return middle(a, b); }

const inlineme_n = globalThis['~Natives_inlineme_n'] ?? (function(){});
const inner  = function(n, a, b) { inlineme_n(n); return a + b; };
const middle = function(a, b) { return inner(1, a, b); };
export function outer(a, b) { return middle(a, b); }

const inlineme_n = globalThis['~Natives_inlineme_n'] ?? (function(){});
const inner  = function(a, b) { inlineme_n(1); return a + b; };
const middle = function(a, b) { const r = inner(a, b); return r; };
export function outer(a, b) { return middle(a, b); }

const inlineme_n = globalThis['~Natives_inlineme_n'] ?? (function(){});
const inner_a = function(a, b) { inlineme_n(2); return a + b; };
const inner_b = function(a, b) { inlineme_n(1); return a * b; };
const middle  = function(a, b) { return inner_a(a, b) + inner_b(a, b); };
export function outer(a, b) { return middle(a, b); }
